        "临终关怀与心理护理：尊重患者尊严与自主权；镇痛、舒适护理、满足心理需求；对家属进行哀伤辅导；尊重临终患者的文化与宗教信仰。",
        "吸痰每次吸引时间不超过15秒（防缺氧），吸痰前后应提高氧流量；测血压袖带过紧、过宽均使测量值偏低，瘫痪或手术患肢不宜测血压应选健侧。",
        "临床见习重点：铺床（暂空床/麻醉床目的与用物）、晨晚间护理内容、出入院护理流程；卧位—头高足低用于颅内压增高、头低足高用于体位引流。",
        "基本测量技术：体温计消毒（含氯消毒液浸泡等）、血压测量四定（定时、定部位、定体位、定袖带）以利前后对比；测脉搏一般30秒×2。",
        "注射法要点：皮内注射（皮试）针头斜面与皮面呈5°、皮下注射30°-40°、肌内注射90°、静脉注射15°-30°；皮试观察20分钟。",
        "输液微粒与空气栓塞防护：排尽空气、及时更换液体、加压输液专人看护；空气栓塞立即左侧头低足高位（左侧卧位并抬高床尾）。",
        "输血护理：先输生理盐水、两袋血之间用生理盐水冲管；输入两份以上血需间隔输注生理盐水；观察输血反应（发热、过敏、溶血）。",
        "临终患者护理：疼痛三阶梯用药原则（口服→按阶梯→按时→个体化），临终关怀重视舒适、尊严与家属心理支持。",
        "健康教育基础：以患者为中心的健康宣教（饮食、体位、活动、用药、随访）、出院指导与心理疏导；沟通采用开放式提问、反馈澄清。",
