            "急性胰腺炎：禁食+胃肠减压+抑酸抑酶+TPN；腹痛放射至腰背、血淀粉酶6-12h升高。",
            "结核病护理：呼吸道隔离、痰涂片阳性者带口罩；化疗方案2个月强化+继续治疗；接触者筛查。"
