        "医院感染与预防：手卫生、无菌原则、隔离技术、医疗废物分类处理。",
        "危急值速记：血钾<2.5或>6.5mmol/L、血糖<2.2mmol/L、血小板<30×10^9/L等需立即报告。",
        "心电图基础知识：正常P-QRS-T、窦性心律判断、常见心律失常图形识别。",
        "检验判读要结合症状体征：Hb降低-贫血、WBC升高-感染/应激、PLT降低-出血倾向、淀粉酶升高-胰腺炎、心肌损伤标志物(cTnI/CK-MB)。",
        "人体九大系统功能记忆：循环运输、呼吸换气、消化吸收、泌尿排泄、神经调节、内分泌激素、运动支持、生殖繁衍、免疫防御。",
        "解剖·骨与胸廓：成人骨共206块，分颅骨、躯干骨、四肢骨；胸骨由胸骨柄、胸骨体、剑突三部分构成，肋骨共12对；躯干骨=椎骨+胸骨+肋骨。",
        "解剖·消化系：食管三处生理性狭窄（起始处距中切牙约15cm、与左主支气管交叉处约25cm、穿膈食管裂孔处约40cm），为异物滞留与食管癌好发部位；胃上口贲门、下口幽门；人体最大消化腺=肝脏、第二=胰腺，胆汁由肝脏分泌、储存于胆囊，不含消化酶只乳化脂肪。",
        "解剖·呼吸系：右主支气管粗短陡直、左主支气管细长倾斜，异物易坠入右主支气管；左肺2叶、右肺3叶；胸膜腔为负压密闭腔隙。",
        "解剖·循环系：心脏四腔中左心室壁最厚；体循环=左心室→主动脉→全身毛细血管→上下腔静脉→右心房；肺循环=右心室→肺动脉→肺毛细血管→肺静脉→左心房。",
        "解剖·泌尿/神经/内分泌：肾单位（肾小体+肾小管）为肾脏基本结构与功能单位，输尿管三处狭窄（肾盂移行处、跨髂血管处、穿膀胱壁处）结石易卡顿；交感神经兴奋心率加快、血压升高、瞳孔散大、支气管扩张、胃肠蠕动抑制，副交感相反；内分泌腺包括垂体、甲状腺、甲状旁腺、肾上腺、胰岛等。",
        "生理·血液与血型：红细胞运输O₂与CO₂；中性粒细胞抗细菌、淋巴细胞抗病毒、血小板参与止血凝血；按ABO同型输血，Rh阴性因缺乏D抗原为“熊猫血”，母Rh阴性胎儿Rh阳性可致新生儿溶血。",
        "生理·呼吸与循环调节：肺通气原动力=呼吸肌（膈肌为主）舒缩，直接动力=肺内压与大气压之差；肺换气动力=肺泡与血液间气体分压差；调节呼吸最重要的化学因素为CO₂（升高→呼吸加深加快）；缺氧主要刺激颈动脉体、主动脉体化学感受器。",
        "生理·消化与肾脏内分泌：胃酸由胃壁细胞分泌，胰液含多种消化酶、消化能力最强；抗利尿激素(ADH)促进远曲小管与集合管重吸收水、使尿量减少，醛固酮保钠排钾；胰岛素是唯一降血糖激素。",
        "病理·坏死与炎症：凝固性坏死（心肾脾）、液化性坏死（脑、脓肿）、坏疽（干性四肢/湿性内脏/气性）、纤维素样坏死（风湿病）；急性炎症以中性粒细胞为主、慢性以淋巴/浆细胞为主；渗出液蛋白高、细胞多、浑浊，漏出液清亮、蛋白低、细胞少。",
        "病理·梗死与常见病理：贫血性梗死（心肾脾）vs出血性梗死（肺肠）；癌来源于上皮组织、肉瘤来源于间叶组织；动脉粥样硬化脂质沉积内膜好发大中动脉，高血压为细小动脉硬化，肝硬化形成假小叶，大叶性肺炎为肺泡纤维素渗出、小叶性肺炎为以细支气管为中心的化脓性炎。",
        "我国法定传染病分三类：甲类（鼠疫、霍乱）、乙类（肺结核、麻疹、新冠等）、丙类（流感、手足口病等）；流感属丙类。",
        "现代医学死亡判定标准＝脑死亡；护理伦理基本原则＝自主、不伤害、有利（行善）、公正。",
        "输液安全：成人40-60滴/分、儿童20-40滴/分；含钾液、抗心律失常药、硝普钠等须严格控制滴速；使用输液泵/注射泵精确给药并监测报警。",
        "无菌操作关键点：无菌物品与非无菌分开放置；取放无菌物品使用无菌持物钳、不跨越无菌区；开启的无菌包/无菌盘有效期24小时，疑污染即弃。",
        "意识与瞳孔评估：GCS总分15分、≤8分为昏迷；瞳孔针尖样提示有机磷中毒或桥脑出血、双侧散大提示脑疝或濒死、双侧不等大提示颅内占位——及时报告并记录。",
        "常用检验危急值补充：血钾<2.5或>6.5mmol/L、血糖<2.2mmol/L、PT/APTT明显延长、血气pH<7.20或>7.55均须立即报告医生处理。",
        "心电图异常波形要点：房颤一R-R间期绝对不等且无P波、室上速一QRS窄而节律齐、室颤一无规律粗乱波无有效泵血；非医务人员协同识别报警。",
        "炎症与肿瘤病理常识：炎症五大局部表现=红、肿、热、痛、功能障碍；癌与肉瘤来源不同（上皮vs间叶）；早期筛查对肿瘤防治意义大。",
        "生理反射与脑卒中定位常识：内囊出血典型为“三偏”综合征（偏瘫、偏盲、偏身感觉障碍）；脑出血常急性起病伴血压升高，救护中保持气道通畅。",
